  8	export default function FormulaBar({ text, activeLabel, onCommit, onCancel }) {
  9	  const ref = useRef(null);
 10	  // Set while an Escape is being handled: the input is about to lose focus (or
 11	  // has already been reset), and blur must not turn the cancelled edit back into
 12	  // a commit.
 13	  const cancelled = useRef(false);
 14	
 15	  const stored = text === undefined || text === null ? '' : String(text);
 16	
 17	  // The parent remounts the input (key = active coordinate) whenever the active
 18	  // cell changes, so the DOM value can be refreshed without fighting the caret.
 19	  useEffect(() => {
 20	    const node = ref.current;
 21	    if (node) node.value = stored;
 22	  }, [stored, activeLabel]);
 23	
 24	  return (
 25	    <div className="formula-bar-row">
 26	      <label htmlFor="formula-bar">Formula bar</label>
 27	      <input
 28	        type="text"
 29	        id="formula-bar"
 30	        name="formula"
 31	        autoComplete="off"
 32	        spellCheck="false"
 33	        aria-label="Formula bar"
 34	        ref={ref}
 35	        defaultValue={text}
 36	        aria-describedby="formula-bar-cell"
 37	        onKeyDown={(event) => {
 38	          if (event.key === 'Enter') {
 39	            event.preventDefault();
 40	            cancelled.current = false;
 41	            onCommit(engine.storedInputFromFormulaBar(event.currentTarget.value));
 42	            return;
 43	          }
 44	          if (event.key === 'Escape') {
 45	            event.preventDefault();
 46	            // Escape abandons the edit: restore the stored input so the bar shows
 47	            // the cell's real content again instead of the abandoned text.
 48	            cancelled.current = true;
 49	            event.currentTarget.value = stored;
 50	            onCancel();
 51	          }
 52	        }}
 53	        onBlur={(event) => {
 54	          if (cancelled.current) {
 55	            cancelled.current = false;
 56	            return;
 57	          }
 58	          const current = event.currentTarget.value;
 59	          if (String(current) === stored) return;
 60	          onCommit(engine.storedInputFromFormulaBar(current));
 61	        }}
 62	      />
 63	      <span id="formula-bar-cell" className="muted formula-cell">
 64	        {activeLabel || 'A1'}
 65	      </span>
 66	    </div>
